import { copyFileSync, existsSync, mkdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { defineConfig, type DefaultTheme } from 'vitepress';
import llmstxt from 'vitepress-plugin-llms';
import { typesInMarkdown } from './declarations.ts';
import { excerptBlocks } from './excerpts.ts';

// Generated by `npm run docs:api`, which the docs scripts run first.
const apiSidebar = JSON.parse(
  readFileSync(new URL('../api/typedoc-sidebar.json', import.meta.url), 'utf8'),
) as DefaultTheme.SidebarItem[];

const base = '/test-inventory/';
const url = `https://huldoser.github.io${base}`;
const { version, description } = JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8')) as {
  version: string;
  description: string;
};

export default defineConfig({
  title: 'test-inventory',
  description,
  base,
  cleanUrls: true,
  lastUpdated: true,
  srcExclude: ['**/README.md'],
  sitemap: { hostname: url },
  // llms.txt, llms-full.txt and a Markdown copy of each page, for coding assistants.
  vite: {
    plugins: [
      typesInMarkdown(),
      llmstxt({
        domain: 'https://huldoser.github.io',
        // Flatten API groups in this index so nested sections retain the site's deployment prefix.
        sidebar: (sidebar) =>
          (sidebar as DefaultTheme.SidebarItem[]).flatMap((section) =>
            section.text === 'API' ? (section.items ?? []) : [section],
          ),
        customLLMsTxtTemplate: `# {title}

> Static test metadata, not execution results. Begin with the compact reference and fetch detailed pages as needed.

## Essential

- [Framework guides](${url}frameworks.md): Choose a runner for commands, examples and relevant limitations.
- [Agent reference](${url}guide/agent-reference.md): Tool selection, pagination, state interpretation and limits.
- [Complete workflow](${url}guide/workflows.md): One query through CLI, library and MCP.
- [CLI](${url}guide/cli.md): Flags, defaults, files and exit codes.
- [Output](${url}reference/output.md): Record keys and schema contracts.
- [Diagnostics](${url}reference/diagnostics.md): Scan gaps and corrective information.
- [Saved scan diffs](${url}guide/diff.md): Matching, hash compatibility and warnings.
- [Compatibility](${url}guide/compatibility.md): Core, MCP and schema versions.
- [MCP tools](https://raw.githubusercontent.com/Huldoser/test-inventory-mcp/main/docs/tools.md): Generated argument and response reference.

## Optional

The complete page index follows, including background, type reference and historical releases. The full bundle is available as [llms-full.txt](${url}llms-full.txt).

{toc}
`,
      }),
    ],
  },
  markdown: { config: excerptBlocks },
  // Links in `head` are written as they are, without the base.
  head: [
    ['link', { rel: 'icon', href: `${base}favicon.ico`, sizes: '32x32' }],
    ['link', { rel: 'icon', href: `${base}favicon.svg`, type: 'image/svg+xml' }],
    ['link', { rel: 'apple-touch-icon', href: `${base}apple-touch-icon.png` }],
    ['meta', { property: 'og:type', content: 'website' }],
    ['meta', { property: 'og:image', content: `${url}social-preview.png` }],
    ['meta', { property: 'og:image:width', content: '1280' }],
    ['meta', { property: 'og:image:height', content: '640' }],
    [
      'meta',
      { property: 'og:image:alt', content: 'test-inventory: test metadata from source code, not from test results.' },
    ],
    ['meta', { name: 'twitter:card', content: 'summary_large_image' }],
  ],
  // The Open Graph tags that differ per page, so that a shared link previews the page it points to.
  transformHead({ pageData, title, description }) {
    const page = pageData.relativePath.replace(/(^|\/)index\.md$/, '$1').replace(/\.md$/, '');
    return [
      ['meta', { property: 'og:title', content: title }],
      ['meta', { property: 'og:description', content: description }],
      ['meta', { property: 'og:url', content: `${url}${page}` }],
    ];
  },
  themeConfig: {
    logo: { light: '/mark-small-light.svg', dark: '/mark-small-dark.svg', alt: 'test-inventory' },
    nav: [
      { text: 'Guide', link: '/guide/getting-started' },
      { text: 'Frameworks', link: '/frameworks/' },
      { text: 'Reference', link: '/reference/output' },
      { text: 'API', link: '/api/' },
      { text: `v${version}`, link: '/changelog' },
      { text: 'About', link: '/about' },
    ],
    sidebar: [
      {
        text: 'Start here',
        items: [
          { text: 'Getting started', link: '/guide/getting-started' },
          { text: 'Choose your framework', link: '/frameworks/' },
          { text: 'One task, three interfaces', link: '/guide/workflows' },
          { text: 'Key concepts', link: '/guide/concepts' },
          { text: 'Examples', link: '/guide/examples' },
        ],
      },
      {
        text: 'Framework guides',
        collapsed: true,
        items: [
          { text: 'Playwright', link: '/frameworks/playwright' },
          { text: 'Vitest', link: '/frameworks/vitest' },
          { text: 'Jest', link: '/frameworks/jest' },
          { text: 'Mocha', link: '/frameworks/mocha' },
          { text: 'Jasmine', link: '/frameworks/jasmine' },
          { text: 'Cypress', link: '/frameworks/cypress' },
          { text: 'WebdriverIO', link: '/frameworks/webdriverio' },
          { text: 'node:test', link: '/frameworks/node' },
          { text: 'Bun', link: '/frameworks/bun' },
        ],
      },
      {
        text: 'Tasks',
        items: [
          { text: 'Compare inventories', link: '/guide/diff' },
          { text: 'Query recipes', link: '/guide/recipes' },
          { text: 'CI recipes', link: '/guide/ci' },
          { text: 'AI agents', link: '/guide/agents' },
          { text: 'Agent reference', link: '/guide/agent-reference' },
          { text: 'Troubleshooting', link: '/guide/troubleshooting' },
        ],
      },
      {
        text: 'Understanding the scan',
        items: [
          { text: 'Why test-inventory', link: '/guide/why' },
          { text: 'Shared limits', link: '/guide/limits' },
          { text: 'Compared with the runners', link: '/guide/runners' },
          { text: 'Real projects', link: '/guide/real-projects' },
        ],
      },
      {
        text: 'Reference',
        items: [
          { text: 'Command line', link: '/guide/cli' },
          { text: 'Library', link: '/guide/library' },
          { text: 'Versions and compatibility', link: '/guide/compatibility' },
          { text: 'Output', link: '/reference/output' },
          { text: 'Supported syntax', link: '/reference/syntax' },
          { text: 'Diagnostics', link: '/reference/diagnostics' },
        ],
      },
      { text: 'API', items: apiSidebar },
    ],
    socialLinks: [
      { icon: 'github', link: 'https://github.com/Huldoser/test-inventory', ariaLabel: 'GitHub repository' },
      { icon: 'githubsponsors', link: 'https://github.com/sponsors/Huldoser', ariaLabel: 'Sponsor on GitHub' },
    ],
    editLink: {
      pattern: 'https://github.com/Huldoser/test-inventory/edit/main/docs/:path',
      text: 'Edit this page on GitHub',
    },
    search: { provider: 'local' },
    footer: {
      message: `Documentation for test-inventory ${version}. Released under the MIT License.`,
      copyright: 'Copyright © 2026 <a href="https://github.com/Huldoser">Andrey Rychkov</a>',
    },
  },
  // Both schemas are published at their $id URLs.
  buildEnd(site) {
    const index = readFileSync(path.join(site.outDir, 'llms.txt'), 'utf8');
    for (const [, href] of index.matchAll(/\]\((https?:\/\/[^)]+)\)/g)) {
      const link = new URL(href);
      if (link.origin !== new URL(url).origin) continue;
      const file = path.join(site.outDir, decodeURIComponent(link.pathname.slice(base.length)));
      if (!link.href.startsWith(url) || !existsSync(file)) {
        throw new Error(`Markdown index link does not resolve in the built site: ${href}`);
      }
    }
    const target = path.join(site.outDir, 'schema');
    mkdirSync(target, { recursive: true });
    for (const file of ['v1.json', 'diff-v1.json']) {
      copyFileSync(path.resolve(site.root, '../schema', file), path.join(target, file));
    }
  },
});
